// Cell values and recalculation.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr } from "./addr.mjs";

const NUMBER = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

// Value of a non-formula cell's raw text.
export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (NUMBER.test(t) && Number.isFinite(Number(t))) return Number(t);
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw[0] === "'") return raw.slice(1);
  return raw;
}

const key = (addr) => { const a = parseAddr(addr); return a.row * 20000 + a.col; };

// Parses every formula cell; returns { asts, deps } (deps only for formulas that parse).
function analyze(sheet) {
  const asts = new Map(), deps = new Map(), bad = new Set();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") continue;
    try {
      const ast = parseFormula(raw.slice(1));
      asts.set(addr, ast);
      deps.set(addr, refsOf(ast).filter((r) => sheet.cells.get(r)?.[0] === "="));
    } catch {
      bad.add(addr);
    }
  }
  for (const [addr, d] of deps) deps.set(addr, d.filter((r) => asts.has(r)));
  return { asts, deps, bad };
}

// Iterative Tarjan; returns SCCs in dependency order (a cell's dependencies come first).
function sccs(deps) {
  const index = new Map(), low = new Map(), on = new Set(), stack = [], out = [];
  let n = 0;
  for (const root of deps.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, n); low.set(root, n++); stack.push(root); on.add(root);
    while (work.length) {
      const top = work[work.length - 1];
      const [v, i] = top;
      const ds = deps.get(v);
      if (i < ds.length) {
        top[1]++;
        const w = ds[i];
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); on.add(w);
          work.push([w, 0]);
        } else if (on.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) {
          const p = work[work.length - 1][0];
          low.set(p, Math.min(low.get(p), low.get(v)));
        }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); on.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const isCycle = (comp, deps) => comp.length > 1 || deps.get(comp[0]).includes(comp[0]);

// Map from every non-empty cell's address to its value.
export function computeAll(sheet) {
  const { asts, deps, bad } = analyze(sheet);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (raw[0] !== "=") values.set(addr, valueOf(raw));
    else if (bad.has(addr)) values.set(addr, "#ERROR!");
  }
  const lookup = (a) => values.get(a) ?? null;
  for (const comp of sccs(deps)) {
    if (isCycle(comp, deps)) for (const a of comp) values.set(a, "#CYCLE!");
    else values.set(comp[0], evaluate(asts.get(comp[0]), lookup));
  }
  const out = new Map();
  for (const addr of sheet.cells.keys()) out.set(addr, values.get(addr));
  return out;
}

// Formula cells reading addr directly or indirectly, in dependency order.
export function dependents(sheet, addr) {
  const { deps } = analyze(sheet);
  const a = (() => { const p = parseAddr(addr); return `${[...Array(0)]}` && null; })();
  void a;
  const cyc = new Set();
  for (const comp of sccs(deps)) if (isCycle(comp, deps)) for (const c of comp) cyc.add(c);
  const rev = new Map();
  for (const [c, ds] of deps) for (const d of ds) (rev.get(d) ?? rev.set(d, []).get(d)).push(c);
  // Direct readers may reference non-formula addr, so build readers from raw refs.
  return order(sheet, addr, deps, rev, cyc);
}
