// Sorting and pivoting of cell ranges.
import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

function parseRange(range) {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return {
    c0: Math.min(p.col, q.col), c1: Math.max(p.col, q.col),
    r0: Math.min(p.row, q.row), r1: Math.max(p.row, q.row),
  };
}

const isEmpty = (v) => v == null || v === "";
const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, then strings (case-insensitive), then booleans (false first).
function compareValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return a - b;
  if (ra === 1) {
    const x = a.toLowerCase(), y = b.toLowerCase();
    return x < y ? -1 : x > y ? 1 : 0;
  }
  return Number(a) - Number(b);
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const start = options.header ? r0 + 1 : r0;
  const rows = [];
  for (let r = start; r <= r1; r++) {
    const raws = [];
    for (let c = c0; c <= c1; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push({ raws, index: r - start });
  }
  const cols = keys.map((k) => ({ i: colIndex(k.col) - c0, desc: !!k.desc }));
  for (const row of rows) {
    row.vals = cols.map((k) => {
      if (k.i < 0 || k.i > c1 - c0) return null;
      const raw = row.raws[k.i];
      return raw === "" ? null : valueOf(raw);
    });
  }
  rows.sort((x, y) => {
    for (let n = 0; n < cols.length; n++) {
      const a = x.vals[n], b = y.vals[n];
      const ea = isEmpty(a), eb = isEmpty(b);
      if (ea || eb) {
        if (ea && eb) continue;
        return ea ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return cols[n].desc ? -d : d;
    }
    return x.index - y.index;
  });
  rows.forEach((row, n) => {
    row.raws.forEach((raw, k) => setCell(sheet, toAddr(c0 + k, start + n), raw));
  });
}

export function pivot(values, range, { rows, value, agg }) {
  const { c0, c1, r0, r1 } = parseRange(range);
  const find = (name) => {
    for (let c = c0; c <= c1; c++) {
      if (String(values.get(toAddr(c, r0)) ?? "") === name) return c;
    }
    throw new Error(`no such column: ${name}`);
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  let blank;
  for (let r = r0 + 1; r <= r1; r++) {
    const k = values.get(toAddr(kc, r)), v = values.get(toAddr(vc, r));
    let list;
    if (isEmpty(k)) list = blank ??= [];
    else {
      list = groups.get(k);
      if (!list) groups.set(k, (list = []));
    }
    list.push(v);
  }
  const aggregate = (vs) => {
    if (agg === "count") return vs.filter((v) => !isEmpty(v)).length;
    const nums = vs.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, v) => s + v, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, v) => s + v, 0) / nums.length;
    if (agg === "min") return Math.min(...nums);
    if (agg === "max") return Math.max(...nums);
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const out = [...groups.keys()].sort(compareValues).map((key) => ({ key, value: aggregate(groups.get(key)) }));
  if (blank) out.push({ key: "(blank)", value: aggregate(blank) });
  return out;
}
